import AppKit
import ClipHistoryCore

final class ClipboardMonitor: NSObject {
    // nspasteboard.org markers that password managers and helper tools set on sensitive or temporary data.
    static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]
    static let ignoredAppsKey = "ignoredBundleIDs"
    static let defaultIgnoredApps = [
        "com.bitwarden.desktop",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.apple.keychainaccess",
        "com.apple.Passwords",
    ]

    var isPaused = false
    var onCapture: (() -> Void)?

    private let store: Store
    private let imagesDirectory: URL
    private let pasteboard = NSPasteboard.general
    private var lastChangeCount: Int
    private var timer: Timer?

    init(store: Store, imagesDirectory: URL) {
        self.store = store
        self.imagesDirectory = imagesDirectory
        lastChangeCount = pasteboard.changeCount
        UserDefaults.standard.register(defaults: [Self.ignoredAppsKey: Self.defaultIgnoredApps])
    }

    func start() {
        let timer = Timer(timeInterval: 0.5, target: self, selector: #selector(tick), userInfo: nil, repeats: true)
        timer.tolerance = 0.1
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func markCurrentContentsAsSeen() {
        lastChangeCount = pasteboard.changeCount
    }

    @objc private func tick() {
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount
        guard !isPaused else { return }
        do {
            if try capture() { onCapture?() }
        } catch {
            NSLog("ClipHistory: capture failed: \(error)")
        }
    }

    private func capture() throws -> Bool {
        let types = pasteboard.types ?? []
        if types.contains(where: { Self.skippedTypes.contains($0.rawValue) }) { return false }

        let source = NSWorkspace.shared.frontmostApplication
        let ignoredApps = UserDefaults.standard.stringArray(forKey: Self.ignoredAppsKey) ?? []
        if let bundleID = source?.bundleIdentifier, ignoredApps.contains(bundleID) { return false }

        let fileURLs = pasteboard.readObjects(
            forClasses: [NSURL.self],
            options: [.urlReadingFileURLsOnly: true]
        ) as? [URL] ?? []

        if !fileURLs.isEmpty {
            let text = fileURLs.map(\.path).joined(separator: "\n")
            let data = Data(text.utf8)
            try store.insert(
                kind: .file, text: text, hash: Store.hash(kind: .file, data: data),
                appName: source?.localizedName, appBundle: source?.bundleIdentifier, byteSize: data.count
            )
            return true
        }

        if let text = pasteboard.string(forType: .string),
           !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let data = Data(text.utf8)
            try store.insert(
                kind: .text, text: text, hash: Store.hash(kind: .text, data: data),
                appName: source?.localizedName, appBundle: source?.bundleIdentifier, byteSize: data.count
            )
            return true
        }

        if let png = pngData(), let bitmap = NSBitmapImageRep(data: png) {
            let hash = Store.hash(kind: .image, data: png)
            let file = imagesDirectory.appendingPathComponent("\(hash).png")
            if !FileManager.default.fileExists(atPath: file.path) {
                try png.write(to: file, options: .atomic)
            }
            try store.insert(
                kind: .image, text: "Image \(bitmap.pixelsWide)×\(bitmap.pixelsHigh)", imagePath: file.path,
                hash: hash, appName: source?.localizedName, appBundle: source?.bundleIdentifier,
                byteSize: png.count
            )
            return true
        }
        return false
    }

    private func pngData() -> Data? {
        if let png = pasteboard.data(forType: .png) { return png }
        guard let tiff = pasteboard.data(forType: .tiff), let bitmap = NSBitmapImageRep(data: tiff) else {
            return nil
        }
        return bitmap.representation(using: .png, properties: [:])
    }
}
